#!/system/bin/sh
B="${0%/*}/bin/busybox"; F="$@"; [ -f "$F" ]||exit 1; base="${F##*/}"; dir="${F%$base}"; [ -n "$dir" ]||dir="./"; OUT="${dir}${base%.*}_MSAPatcher_Protection.txt"; L="$($B unzip -qql "$F" 2>/dev/null|$B sed 's|.* ||g')"; tmp="${dir}.mpatcher_prot_$$"; for d in $(echo "$L"|$B grep -E '^classes([0-9]*)?\.dex$'); do $B unzip -p "$F" "$d" 2>/dev/null; done > "$tmp"
jiagu="$(echo "$L"|$B grep -Eic 'jiagu|jgdtc|\.jgapp')"; pair="$(echo "$L"|$B grep -Eic 'pairip')"; prot="$(echo "$L"|$B grep -Eic 'protect|shell|packer|stub')"; dyn="$($B grep -aiEo 'DexClassLoader|PathClassLoader|DexFile|loadDex' "$tmp"|$B wc -l|$B tr -d ' ')"; integ="$($B grep -aiEo 'SigningInfo|GET_SIGNATURES|certificate|integrity|tamper' "$tmp"|$B wc -l|$B tr -d ' ')"; dbg="$($B grep -aiEo 'TracerPid|isDebuggerConnected|ptrace' "$tmp"|$B wc -l|$B tr -d ' ')"; visibility=FULL; [ "$dyn" -gt 0 ]&&visibility=PARTIAL; [ "$jiagu" -gt 0 ]&&visibility=PARTIAL
{ echo "MSAPatcher 6.2 - Protection Audit"; echo "APK: $base"; echo; echo "Static analysis visibility: $visibility"; echo "Jiagu markers: $jiagu"; echo "PairIP markers: $pair"; echo "Protection/stub filenames: $prot"; echo "Dynamic loading markers: $dyn"; echo "Signature/integrity markers: $integ"; echo "Anti-debug indicators: $dbg"; echo; echo "Report-only: no protection or integrity mechanism is disabled."; } > "$OUT"; $B rm -f "$tmp"; cat "$OUT"